input.command:
cd "C:/Users/Jesus/Desktop/reto-kontaktu-v2/reto-kontaktu" && python - <<'EOF'
import json,glob
for f in sorted(glob.glob("eventos/*.json")):
    e=json.load(open(f,encoding="utf-8"))
    t=e.get("telephony") or {}
    amd=t.get("amd") or {}
    ao=e.get("agent_outcome") or {}
    print(f"\n=== {f} {e['event_id']} {e['type']} {e['occurred_at']} org={e['organization_id']} idem={e['idempotency_key']} lead={e['lead']['contact_id']} deliv={e.get('delivery_attempt')}")
    if t: print(f"  sip={t.get('sip_status_code')} {t.get('sip_status')} disc={t.get('disconnect_reason')} hung={t.get('hung_up_by')} dur={t.get('duration_seconds')} amd={amd.get('result')}/{amd.get('source')} greet={amd.get('greeting_transcript')!r}")
    if ao: print("  appt=",ao.get("appointment"),"slots=",ao.get("slots_snapshot"))
    for k in e:
        if k not in("telephony","agent_outcome","transcript","lead","campaign"): pass
    if e['type']=='message.received': print("  ",{k:v for k,v in e.items() if k not in('lead','campaign')})
    for u in e.get("transcript") or []:
        print("   ",u.get("role") or u.get("speaker"),":",u.get("text"))
EOF

