let DEC = {}, ORD = {}, RES = null, sel = 0;

const $ = s => document.querySelector(s);
const esc = s => String(s ?? "").replace(/[&<>]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;"}[c]));
const hora = s => s ? new Date(s).toLocaleString("es-ES",
  {weekday:"short", day:"numeric", month:"short", hour:"2-digit", minute:"2-digit",
   timeZone:"Europe/Madrid"}) : "—";

$("#dir").addEventListener("change", async e => {
  DEC = {}; ORD = {}; RES = null;
  for (const f of e.target.files) {
    const txt = await f.text();
    const lineas = txt.split("\n").filter(l => l.trim());
    if (f.name === "decisiones.jsonl") lineas.forEach(l => { const d = JSON.parse(l); DEC[d.event_id] = d; });
    else if (f.name === "ordenes.jsonl") lineas.forEach(l => { const o = JSON.parse(l);
      (ORD[o.event_id] = ORD[o.event_id] || []).push(o); });
    else if (f.name === "resultado.json") RES = JSON.parse(txt);
  }
  const n = Object.keys(DEC).length;
  $("#estado").textContent = n ? `${n} decisiones · ${Object.values(ORD).flat().length} órdenes`
                               : "no se encontró decisiones.jsonl";
  pintar();
});

function evalDe(i) {
  if (!RES) return null;
  return RES.eventos.find(e => e.event_id === EVENTOS[i].event_id) || null;
}

function pintar() {
  const cola = $("#cola");
  let html = "";
  if (RES) {
    const s = RES.resumen;
    html += `<div class="marcador">
      <div><b>${s.ok}/${s.total}</b>eventos</div>
      <div><b>${s.etiquetas_ok}/${s.total}</b>etiquetas</div>
      <div><b>${s.ordenes_ok}/${s.ordenes_esperadas}</b>órdenes</div>
      <div><b>${s.criticos_fallados}</b>críticos fallados</div></div>`;
  }
  EVENTOS.forEach((ev, i) => {
    const d = DEC[ev.event_id], ok = evalDe(i);
    let pill = "";
    if (ok) pill = ok.ok ? `<span class="pill ok">ok</span>`
      : `<span class="pill ${ok.severidad === "critica" ? "crit" : "mal"}">${ok.severidad === "critica" ? "crítico" : "falla"}</span>`;
    else if (d) pill = `<span class="pill">${esc(d.etiqueta)}</span>`;
    const nOrd = (ORD[ev.event_id] || []).length;
    html += `<div class="fila" data-i="${i}" aria-selected="${i === sel}">
      <div class="n">${String(i + 1).padStart(2, "0")}</div>
      <div><div class="nom">${esc(ev.lead.full_name || "—")}</div>
        <div class="meta">${hora(ev.occurred_at)} · ${ev.type === "message.received" ? "WhatsApp entrante"
          : (ev.telephony?.answered_at ? ev.telephony.duration_seconds + " s" : "sin descuelgue")}
          ${nOrd ? " · " + nOrd + " órdenes" : ""}</div></div>
      <div>${pill}</div></div>`;
  });
  cola.innerHTML = html;
  cola.querySelectorAll(".fila").forEach(f =>
    f.onclick = () => { sel = +f.dataset.i; pintar(); detalle(); });
  detalle();
}

function detalle() {
  const ev = EVENTOS[sel], d = DEC[ev.event_id], ords = ORD[ev.event_id] || [], r = evalDe(sel);
  let h = `<h2>${esc(ev.lead.full_name || "—")} <span class="sub mono">${esc(ev.event_id)}</span></h2>`;

  if (r && r.nota) h += `<div class="nota"><b>Nota del corrector:</b> ${esc(r.nota)}</div>`;

  h += `<table><tr><th>Tipo</th><td class="mono">${esc(ev.type)}</td></tr>
    <tr><th>Ocurrió</th><td>${hora(ev.occurred_at)}</td></tr>
    <tr><th>Organización</th><td class="mono">${esc(ev.organization_id)}</td></tr>
    <tr><th>Clave idempotencia</th><td class="mono">${esc(ev.idempotency_key)}</td></tr>
    <tr><th>Inmueble</th><td>${esc(ev.lead.property_ref || "—")} · ${esc(ev.lead.property_address || "dirección no disponible")}</td></tr>`;

  if (ev.telephony) { const t = ev.telephony;
    h += `<tr><th>SIP</th><td class="mono">${t.sip_status_code} ${esc(t.sip_status || "")}</td></tr>
      <tr><th>Desconexión</th><td class="mono">${esc(t.disconnect_reason)} · colgó ${esc(t.hung_up_by || "—")}</td></tr>
      <tr><th>Descuelgue</th><td>${t.answered_at ? hora(t.answered_at) : "nunca"} · ${t.duration_seconds} s</td></tr>
      <tr><th>Contestador</th><td class="mono">${t.amd ? esc(t.amd.result) + (t.amd.source ? " (" + esc(t.amd.source) + ")" : "") : "(no viene)"}</td></tr>`;
    if (t.amd && t.amd.greeting_transcript)
      h += `<tr><th>Saludo oído</th><td><i>«${esc(t.amd.greeting_transcript)}»</i></td></tr>`;
  }
  if (ev.agent_outcome) { const a = ev.agent_outcome;
    if (a.appointment) h += `<tr><th>Cita creada</th><td class="mono">${esc(a.appointment.appointment_id)} · ${hora(a.appointment.start_time)}</td></tr>`;
    if (a.slots_snapshot && Object.keys(a.slots_snapshot).length)
      h += `<tr><th>Slots recogidos</th><td class="mono">${esc(JSON.stringify(a.slots_snapshot))}</td></tr>`;
  }
  if (ev.message) h += `<tr><th>Mensaje</th><td>«${esc(ev.message.text)}»</td></tr>`;
  h += `</table>`;

  if (ev.transcript && ev.transcript.length) {
    h += `<h2>Transcripción</h2>`;
    ev.transcript.forEach(t => h += `<div class="turno"><div class="seg">${t.time_in_call_secs}s</div>
      <div class="quien ${t.role === "agent" ? "agente" : ""}">${t.role === "agent" ? "agente" : "lead"}</div>
      <div>${esc(t.message)}</div></div>`);
  } else if (ev.type === "call.ended") {
    h += `<h2>Transcripción</h2><p class="sub">Sin conversación.</p>`;
  }

  h += `<h2>Decisión</h2>`;
  h += d ? `<table><tr><th>Etiqueta</th><td class="mono">${esc(d.etiqueta)}${
      r && r.etiqueta_esperada !== d.etiqueta ? ` <span class="pill mal">esperada: ${esc(r.etiqueta_esperada)}</span>` : ""}</td></tr>
    <tr><th>Motivo</th><td>${esc(d.motivo)}</td></tr>
    <tr><th>Confianza</th><td class="mono">${d.confianza}</td></tr></table>`
    : `<p class="sub">Sin decisión para este evento.${r ? ` Se esperaba <code>${esc(r.etiqueta_esperada)}</code>.` : ""}</p>`;

  h += `<h2>Órdenes</h2>`;
  if (r) {
    if (!r.ordenes.length) h += `<p class="sub">No se esperaba ninguna orden${ords.length ? ", y se emitieron " + ords.length : ", y no se emitió ninguna"}.</p>`;
    r.ordenes.forEach(o => {
      h += `<div class="orden ${o.ok ? "ok" : "mal"}"><div class="op">${esc(o.operacion)}</div>`;
      o.motivos.forEach(m => h += `<div class="fallo">${esc(m)}</div>`);
      if (o.cuerpo_recibido) h += `<pre>${esc(JSON.stringify(o.cuerpo_recibido, null, 1))}</pre>`;
      h += `</div>`;
    });
  } else if (ords.length) {
    ords.forEach(o => h += `<div class="orden"><div class="op">${esc(o.operacion)}</div>
      <pre>${esc(JSON.stringify(o.cuerpo, null, 1))}</pre></div>`);
  } else {
    h += `<p class="sub">Ninguna.</p>`;
  }
  $("#detalle").innerHTML = h;
}
pintar();
</script></body></html>

